tic = {\n  name: 'GanttElastic',\n  components: {\n    MainView,\n    GanttHeader: Header\n  },\n  props: ['tasks', 'options', 'dynamicStyle'],\n  provide() {\n    const provider = {};\n    const self = this;\n    Object.defineProperty(provider, 'root', {\n      enumerable: true,\n      get: () => self\n    });\n    return provider;\n  },\n  data() {\n    return {\n      state: {\n        tasks: [],\n        options: {\n          scrollBarHeight: 0,\n          allVisibleTasksHeight: 0,\n          outerHeight: 0,\n          scroll: {\n            left: 0,\n            top: 0\n          }\n        },\n        dynamicStyle: {},\n        selectedTaskId: null,\n        hoveredTaskId: null,\n        now: Date.now(),\n        nowTimer: null,\n        delegation: null,\n        refs: {},\n        tasksById: {},\n        taskTree: {},\n        ctx,\n        emitTasksChanges: true, // some operations may pause emitting changes to parent component\n        emitOptionsChanges: true, // some operations may pause emitting changes to parent component\n        resizeObserver: null,\n        unwatchTasks: null,\n        unwatchOptions: null,\n        unwatchStyle: null,\n        unwatchVisibleTasksGeometry: null,\n        initialized: false,\n        unwatchOutputTasks: null,\n        unwatchOutputOptions: null,\n        unwatchOutputStyle: null\n      }\n    };\n  },\n  methods: {\n    mergeDeep,\n    mergeDeepReactive,\n\n    /**\n     * Register a child component element in the shared refs registry.\n     * Children call this from mounted() instead of writing\n     * root.state.refs directly - the one discoverable seam for DOM access.\n     *\n     * @param {string} name registry key (chartContainer, taskListItems, ...)\n     * @param {element} ref the mounted element\n     */\n    registerRef(name, ref) {\n      this.state.refs[name] = ref;\n    },\n\n    /**\n     * Emit an event on both channels: the component $emit (template\n     * listeners) and the internal event bus (prog